        this.addAnnotation((ENamedElement)this.getPortPrototype_ParameterPortAnnotations(), source, new String[]{"documentation", "Annotations on this parameter port."});
        this.addAnnotation((ENamedElement)this.getPortPrototype_SenderReceiverAnnotations(), source, new String[]{"documentation", "Collection of annotations of this ports sender/receiver communication."});
        this.addAnnotation((ENamedElement)this.getPortPrototype_TriggerPortAnnotations(), source, new String[]{"documentation", "Annotations on this trigger port."});
        this.addAnnotation((ENamedElement)this.getPortPrototype_VariationPoint(), source, new String[]{"documentation", "This element was generated/modified due to an atpVariation stereotype."});
